package com.sumedha.commerce.user.controller; import com.sumedha.commerce.user.dto.response.*; import com.sumedha.commerce.user.enums.AddressType; import com.sumedha.commerce.user.exception.GlobalExceptionHandler; import com.sumedha.commerce.user.service.UserProfileService; import com.sumedha.commerce.common.core.exception.*; import org.junit.jupiter.api.*; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import java.util.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class UserProfileControllerTest {MockMvc mvc;UserProfileService service;UUID id=UUID.randomUUID();@BeforeEach void set(){service=mock(UserProfileService.class);mvc=MockMvcBuilders.standaloneSetup(new UserProfileController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();}@Test void profileEndpointsMapSuccessAndErrors()throws Exception{when(service.create(eq(id),any())).thenReturn(new UserProfileResponse(UUID.randomUUID(),id,"A","B",null,null,null));mvc.perform(post("/api/v1/users/{id}/profile",id).contentType(MediaType.APPLICATION_JSON).content("{\"firstName\":\"A\",\"lastName\":\"B\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.success").value(true));when(service.get(id)).thenThrow(new ResourceNotFoundException("Profile not found"));mvc.perform(get("/api/v1/users/{id}/profile",id)).andExpect(status().isNotFound());mvc.perform(post("/api/v1/users/{id}/profile",id).contentType(MediaType.APPLICATION_JSON).content("{")).andExpect(status().isBadRequest());}@Test void addressAndPreferencesEndpointsMap()throws Exception{when(service.addresses(id)).thenReturn(List.of());mvc.perform(get("/api/v1/users/{id}/addresses",id)).andExpect(status().isOk()).andExpect(jsonPath("$.success").value(true));doNothing().when(service).deleteAddress(eq(id),any());mvc.perform(delete("/api/v1/users/{id}/addresses/{aid}",id,UUID.randomUUID())).andExpect(status().isNoContent());when(service.preferences(id)).thenReturn(new UserPreferencesResponse("en","USD",false,true));mvc.perform(get("/api/v1/users/{id}/preferences",id)).andExpect(status().isOk());}}
